#include "viewer.h"
#include <cmath>
namespace spng {
static QString configDescription(const QJsonObject& config){
    // Preserve the reference application's field order and numeric presentation.
    const QStringList order={"scale","interpolation","highpass","taps","cutoff","z_filter","z_weight","z_step","binary","threshold","dilation"};
    const QSet<QString> realFields={"scale","cutoff","z_weight","threshold"};
    QStringList fields;
    for(const auto& key:order){
        auto encoded=QJsonDocument(QJsonArray{config.value(key)}).toJson(QJsonDocument::Compact);
        QString value=QString::fromUtf8(encoded.mid(1,encoded.size()-2));
        if(realFields.contains(key)&&!value.contains('.')&&!value.contains('e'))value+=".0";
        fields.append('"'+key+"\": "+value);
    }
    return '{'+fields.join(", ")+'}';
}
QString Viewer::stage()const{return combo("stage_combo")->currentText();}
Reader Viewer::reader()const{if(stage()!="元画像"&&processed){auto bank=processed;auto s=stage();return [bank,s](int i){return bank->read(i,s);};}if(rawBank){auto bank=rawBank;return [bank](int i){return bank->read(i,"元画像");};}auto s=stack;return [s](int i){if(!s)return Image{};return s->read(i);};}
void Viewer::stageChanged(){if(!stack)return;stopPlay();projection.reset();frameCache.clear();cacheOrder.clear();cacheBytes=0;levelsInitialized=false;invalidate({"frame"});requestLayer();}
void Viewer::togglePlay(){if(playing){stopPlay();return;}if(!stack||bulkRunning)return;if(spin("play_start")->value()>spin("play_end")->value()){QMessageBox::warning(this,"再生範囲","開始層≦終了層にしてください。");return;}if(check("preload_check")->isChecked()&&!rawBank&&stage()=="元画像"){startPreload(true);return;}beginPlay();}
void Viewer::beginPlay(){bool wasProjection=bool(projection);projection.reset();playing=true;button("play_button")->setText("⏸ 一時停止");int a=spin("play_start")->value(),b=spin("play_end")->value(),i=spin("layer_number")->value();if(i<a||i>=b)spin("layer_number")->setValue(a);if(wasProjection)requestLayer();else if(image.empty()&&!loadingImage)loadRequestedLayer();playTimer.start(std::max(1,int(std::nearbyint(1000/real("play_rate")->value()))));}
void Viewer::stopPlay(){playing=false;playTimer.stop();button("play_button")->setText("▶ 再生");}
void Viewer::schedulePlay(){/* The timer is set by beginPlay/playTick, not by image decoding. */}
void Viewer::playTick(){if(!playing||!stack)return;if(loadingImage){playTimer.start(10);return;}int a=spin("play_start")->value(),b=spin("play_end")->value();if(a>b){stopPlay();label("state_label")->setText("再生範囲は開始層≦終了層にしてください。");return;}int n=spin("layer_number")->value()+spin("play_step")->value();if(n>b){if(check("loop_check")->isChecked())n=a;else{stopPlay();return;}}spin("layer_number")->setValue(n);playTimer.start(std::max(1,int(std::nearbyint(1000/real("play_rate")->value()))));}
static QString pointLabel(const std::optional<Point>* points){QStringList text;for(int i=0;i<2;i++){auto p=points[i];text<< (p?QString("点%1: 層%2、X=%3、Y=%4").arg(i+1).arg(p->z).arg(p->x,0,'f',2).arg(p->y,0,'f',2):QString("点%1: 未登録").arg(i+1));}return text.join('\n');}
void Viewer::resetPoint(int tag){check("follow_check")->setChecked(false);points[tag].reset();for(QString axis:{"z","x","y"}){auto name=QString("point%1_%2").arg(tag).arg(axis);auto field=qobject_cast<QAbstractSpinBox*>(objects.value(name));if(auto i=qobject_cast<QSpinBox*>(field))i->setValue(0);else qobject_cast<QDoubleSpinBox*>(field)->setValue(0);field->clear();}label("track_label")->setText(pointLabel(points));centerFollow();}
void Viewer::armPoint(int tag){if(image.empty())return;if(projection){QMessageBox::information(this,"点の指定","通常の層表示へ戻してから点を指定してください。");return;}view->armPoint(tag);label("state_label")->setText(QString("点%1：画像内の位置を左クリックしてください（現在の層 %2）。").arg(tag+1).arg(spin("layer_number")->value()));}
void Viewer::pickedPoint(int tag,int x,int y){if(image.empty()||!stack)return;auto r=stack->frames[spin("layer_number")->value()];if(!r.width||!r.height)return;double sx=double(image.size().width())/r.width,sy=double(image.size().height())/r.height;auto name=[tag](const char* axis){return QString("point%1_%2").arg(tag).arg(axis).toUtf8();};spin(name("z"))->setValue(spin("layer_number")->value());real(name("x"))->setValue((x+.5)/sx-.5);real(name("y"))->setValue((y+.5)/sy-.5);registerPoint(tag);}
void Viewer::registerPoint(int tag){if(!stack)return;auto name=[tag](const char* axis){return QString("point%1_%2").arg(tag).arg(axis).toUtf8();};points[tag]=Point{spin(name("z"))->value(),real(name("x"))->value(),real(name("y"))->value()};label("track_label")->setText(pointLabel(points));if(points[0]&&points[1]){if(points[0]->z==points[1]->z){check("follow_check")->setChecked(false);QMessageBox::warning(this,"点の層","2点は異なる層にしてください。");return;}check("follow_check")->setChecked(true);centerFollow();}}
void Viewer::rangeToPoints(){if(points[0]&&points[1]){spin("play_start")->setValue(std::min(points[0]->z,points[1]->z));spin("play_end")->setValue(std::max(points[0]->z,points[1]->z));}}
void Viewer::centerFollow(){if(closing)return;bool enabled=check("follow_check")->isChecked()&&!image.empty()&&!projection&&points[0]&&points[1];if(!enabled){for(auto item:centerCross)item->hide();if(!check("follow_check")->isChecked())view->trackingActive=false;return;}if(!stack||points[0]->z==points[1]->z)return;auto pos=linePosition(*points[0],*points[1],spin("layer_number")->value(),check("extend_check")->isChecked());auto r=stack->frames[spin("layer_number")->value()];if(!r.width||!r.height)return;double x=(pos.x()+.5)*image.size().width()/r.width-.5,y=(pos.y()+.5)*image.size().height()/r.height-.5;view->centerOnPixel(x,y);double radius=7/std::max(.001,view->transform().m11()),cx=x+.5,cy=image.size().height()-.5-y;centerCross[0]->setLine(cx-radius,cy,cx+radius,cy);centerCross[1]->setLine(cx,cy-radius,cx,cy+radius);for(auto item:centerCross)item->show();}
void Viewer::cancelBulk(){if(cancellation){cancellation->store(true);label("state_label")->setText("中止を待っています…");}}
void Viewer::startPreload(bool playAfter){if(!stack)return;auto s=stack;beginBulk("全層を先読み中…",[s](Progress p,Cancel c){return preload(*s,p,c);},[this,playAfter](BankPtr bank){rawBank=bank;label("state_label")->setText(QString("全層先読み完了（%1秒）").arg(bank->metadata["elapsed_seconds"].toDouble(),0,'f',2));if(playAfter)beginPlay();else loadRequestedLayer();});}
void Viewer::startProcessing(){if(!stack)return;if(check("scan_auto")->isChecked()&&(scanPending||scanError)){QMessageBox::warning(this,"スキャン設定","読み込みが完了していません。設定を確認するか、自動読み込みをOFFにしてください。");return;}FilterConfig c;try{c=filterConfig();c.validate();}catch(const std::exception&e){QMessageBox::warning(this,"処理条件",QString::fromUtf8(e.what()));return;}auto s=stack;QJsonObject context;if(scanSettings){context=scanSettings->metadata();context["applied_threshold"]=c.threshold;context["applied_config_matches_loaded"]=c.json()==scanSettings->config.json();}beginBulk("全層の画像処理を開始…",[s,c](Progress p,Cancel cancel){return process(*s,c,p,cancel);},[this,context](BankPtr bank){if(!context.isEmpty())bank->metadata["scan_parameters"]=context;processed=bank;{QSignalBlocker b(combo("stage_combo"));combo("stage_combo")->clear();combo("stage_combo")->addItems(QStringList{"元画像"}+bank->stages);combo("stage_combo")->setCurrentText(bank->stages.last());}label("process_info")->setText(QString("全%1層の処理完了：%2秒。\n適用済み条件：%3").arg(bank->valid.size()).arg(bank->metadata["elapsed_seconds"].toDouble(),0,'f',2).arg(configDescription(bank->metadata["config"].toObject())));stageChanged();});}
void Viewer::startProjection(QString kind){if(!stack)return;QVector<int> indices;try{indices=parseLayers(get<QLineEdit>("layer_spec")->text(),int(stack->frames.size()));}catch(const std::exception&e){QMessageBox::warning(this,"層の指定",QString::fromUtf8(e.what()));return;}auto read=reader();auto source=stage();beginBulk("重ね合わせを計算中…",[read,indices,kind,source](Progress p,Cancel c){return project(read,indices,kind,source,p,c);},[this](ProjectionPtr value){projection=value;renderProjection();});}
void Viewer::renderProjection(){if(!projection)return;auto p=projection;stopPlay();invalidate({"frame"});debounce.stop();loadingImage=false;image=projectionImage(*p,check("depth_check")->isChecked(),check("depth_weight")->isChecked(),combo("palette_combo")->currentData().toString());loadedIndex=spin("layer_number")->value();if(check("depth_check")->isChecked()){QSignalBlocker b(check("invert"));check("invert")->setChecked(false);}levelsInitialized=true;auto levels=defaultLevels(image);setLevels(levels.first,levels.second);refreshDisplay();int w=image.size().width(),h=image.size().height();spin("roi_x")->setMaximum(w-1);spin("roi_y")->setMaximum(h-1);spin("roi_w")->setMaximum(w);spin("roi_h")->setMaximum(h);QString name=p->kind=="max"?"最大値":"最小値";label("filename")->setText(QString("%1　／　%2　／　%3：%4-%5").arg(QFileInfo(currentPath).fileName(),p->source,name).arg(p->requested.first()).arg(p->requested.last()));label("meta")->setText(QString("%1 × %2 pixel\n%3合成：指定%4層、使用%5層\n同値は最も小さい層番号を採用").arg(w).arg(h).arg(name).arg(p->requested.size()).arg(p->used.size()));label("state_label")->setText("重ね合わせを表示中。通常の層に戻すには層送り、または「通常の層表示へ戻る」。");auto palette=combo("palette_combo")->currentData().toString();label("depth_legend")->setPixmap(QPixmap::fromImage(paletteBar(palette,1)).scaled(300,12));label("depth_legend")->setVisible(check("depth_check")->isChecked());label("depth_text")->setText(QString("左端：層%1 → 右端：層%2（%3）\n同値は最も小さい層番号。色分けの保存はRGB画像です。").arg(p->requested.first()).arg(p->requested.last()).arg(palette));for(auto item:centerCross)item->hide();updateControls();}
void Viewer::returnToSlice(){projection.reset();if(stack)requestLayer();}
}
